### 自动告警流程

```javascript
// 在UnifiedLogger中集成
class UnifiedLogger {
    constructor() {
        // ... 现有代码

        // 🆕 集成AI工作流监控
        if (this.pageId === 'mindmap' || this.pageId === 'main') {
            this.aiMonitor = new AIDevWorkflowMonitor(this);
            this.aiMonitor.startMonitoring();
        }
    }

    // 拦截关键操作
    info(category, message, data) {
        // 检测代码活动
        if (this._isCodeActivity(category, message)) {
            // 自动触发检查
            this.aiMonitor.checkCodeActivity({
                category,
                message,
                data,
                timestamp: Date.now()
            }).then(result => {
                if (!result.passed) {
                    // 🚨 自动告警
                    this.warn('AI_WORKFLOW', '⚠️ 架构对齐检查失败', result);
                    this._showAlert(result);
                }
            });
        }

        // 继续正常日志记录
        // ...
    }

    _isCodeActivity(category, message) {
        // 识别代码活动
        const codeKeywords = ['创建', '修改', '删除', '保存', '初始化'];
        return codeKeywords.some(kw => message.includes(kw));
    }

    _showAlert(result) {
        // 页面弹窗告警
        if (typeof alert !== 'undefined') {
            alert(`⚠️ AI开发规范检查失败\n\n${result.reason}\n\n建议：${result.suggestion}`);
        }

        // 发送到告警中心
        if (window.AutogenEventBus) {
            window.AutogenEventBus.emit('ai:workflow:violation', result);
        }
    }
}
```

