## 🎯 方案1：写入前审查（主动式）

### 触发流程

```javascript
// AI在写入代码前，必须先调用审查
async function aiWriteCode(code, metadata) {
    // 1️⃣ 触发点：AI调用审查API
    const reviewResult = await window.AIWorkflowMonitor.reviewBeforeWrite({
        code: code,
        filename: metadata.filename,
        purpose: metadata.purpose,
        aiAgent: 'cascade'
    });

    // 2️⃣ 检查结果
    if (!reviewResult.approved) {
        // 🚫 不合规，阻止写入
        console.error('❌ 代码审查未通过:', reviewResult.violations);
        alert(`代码审查失败：\n${reviewResult.violations.join('\n')}`);
        return false;
    }

    // 3️⃣ 合规，允许写入
    await writeFile(metadata.filename, code);
    console.log('✅ 代码已写入:', metadata.filename);
    return true;
}
```

### 触发条件

**AI必须在以下操作前调用审查**：
- `write_to_file` - 创建新文件
- `Edit` - 修改现有文件
- `MultiEdit` - 批量修改

### 实现方式

**在AI的工具调用中拦截**：
```javascript
// 拦截write_to_file工具
const originalWriteToFile = tools.write_to_file;
tools.write_to_file = async function(params) {
    // 🔍 触发审查
    const review = await AIWorkflowMonitor.reviewBeforeWrite({
        targetFile: params.TargetFile,
        codeContent: params.CodeContent
    });

    if (!review.approved) {
        throw new Error(`代码审查失败: ${review.reason}`);
    }

    // 通过审查，执行原始操作
    return originalWriteToFile(params);
};
```

