    }

    async getArchitecture() {
        if (this.architectureCache) {
            return this.architectureCache;
        }

        // 读取架构清单
        const response = await fetch('docs/审查员：项目管理应用架构功能清单.md');
        const content = await response.text();

        this.architectureCache = this.parseArchitecture(content);
        return this.architectureCache;
    }

    async checkRedundancy(params) {
        const architecture = await this.getArchitecture();
        const existingModules = architecture.modules.filter(m => 
            m.purpose.includes(params.purpose)
        );

        return {
            score: existingModules.length > 0 ? 0.8 : 0,
            existingModules: existingModules.map(m => m.name)
        };
    }

    // ========== 核心审查逻辑 ==========

    async comprehensiveReview(params) {
        const checks = await Promise.all([
            this.checkArchitectureAlignment(params),
            this.checkModuleCompliance(params),
            this.checkRedundancy(params)
        ]);

        const violations = checks.filter(c => !c.passed);
        const approved = violations.length === 0;

        return {
            approved,
            score: approved ? 100 : 100 - (violations.length * 30),
            violations: violations.map(v => v.message),
            suggestions: violations.map(v => v.suggestion),
            architectureCheck: checks[0],
            moduleCheck: checks[1],
            redundancyCheck: checks[2]
        };
    }

    // ========== 暴露API ==========

    static init() {
        const instance = new AIWorkflowMonitor();
        window.AIWorkflowMonitor = { instance };

        // 自动拦截
        instance.interceptCascadeTools();

        // 暴露手动API
        window.aiReview = async (params) => instance.manualReview(params);
        window.aiReview.getArchitecture = async () => instance.getArchitecture();
        window.aiReview.checkRedundancy = async (params) => instance.checkRedundancy(params);

        console.log('✅ AI工作流监控已启动（自动+手动）');
    }
}

